"""Public character Trade links generated by poe.ninja's visible item dialog."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from urllib.parse import parse_qs, unquote, urlsplit


@dataclass(frozen=True)
class NativeTradeItem:
    name: str
    url: str
    is_jewel: bool


@dataclass(frozen=True)
class NativeTradeResult:
    items: tuple[NativeTradeItem, ...]
    equipped_count: int

    @property
    def unavailable_count(self) -> int:
        return max(0, self.equipped_count - len(self.items))


def valid_native_trade_url(url: str, league_name: str) -> bool:
    """Accept only the official PoE2 Trade search generated for this league."""
    if not isinstance(url, str) or len(url) > 12_000:
        return False
    try:
        parts = urlsplit(url)
        port = parts.port
        payloads = parse_qs(parts.query, keep_blank_values=False).get("q", [])
        query = json.loads(payloads[0]) if len(payloads) == 1 else None
    except (ValueError, TypeError, json.JSONDecodeError):
        return False
    path_prefix = "/trade2/search/"
    if (
        parts.scheme != "https"
        or parts.hostname not in {"pathofexile.com", "www.pathofexile.com"}
        or port not in {None, 443}
        or parts.username is not None
        or parts.password is not None
        or not parts.path.startswith(path_prefix)
        or unquote(parts.path[len(path_prefix) :]).casefold() != league_name.casefold()
        or parts.fragment
        or not isinstance(query, dict)
        or not isinstance(query.get("query"), dict)
    ):
        return False
    return True


def format_native_trade_messages(
    result: NativeTradeResult | None,
    source_url: str,
    max_chars: int = 4500,
) -> list[str]:
    """Keep every clickable URL intact while splitting long lists for chat."""
    if result is None:
        return [
            "poe.ninja 原生装备市集链接：暂时无法从公开角色页读取。"
            f"请打开角色详情页，在装备上点击 Trade：\n{source_url}"
        ]
    if not result.items:
        return [
            "poe.ninja 原生装备市集链接：当前角色页没有生成可用的交易链接。"
            f"请在角色详情页检查装备：\n{source_url}"
        ]

    lines = []
    for index, item in enumerate(result.items, 1):
        name = re.sub(r"\s+", " ", item.name).strip()
        category = "珠宝" if item.is_jewel else "装备"
        lines.append(f"{index}. {category} · {name}：{item.url}")
    chunks: list[str] = []
    current = ""
    for line in lines:
        if current and len(current) + len(line) + 1 > max_chars:
            chunks.append(current)
            current = ""
        current = f"{current}\n{line}" if current else line
    if current:
        chunks.append(current)

    heading = (
        f"poe.ninja 原生装备市集链接（已取得 {len(result.items)}/"
        f"{result.equipped_count} 件）："
    )
    if result.unavailable_count:
        heading += "\n部分装备未生成链接，可在角色页手动点击 Trade。"
    return [f"{heading}\n第 {index}/{len(chunks)} 段\n{chunk}" for index, chunk in enumerate(chunks, 1)]
